/bin/bash -lc "PYTHONDONTWRITEBYTECODE=1 python3 - <<'PY'
from logic import parse_port

for value in (None, 80, b'80', '', '0', '000', '+80', '-80', '80 ', '80\\n', '1_0', '１２', '١٢', '²', '65536', '9' * 10000):
    assert parse_port(value) is None, repr(value)
for value, expected in [('1', 1), ('65535', 65535), ('00080', 80), ('0' * 10000 + '1', 1)]:
    assert parse_port(value) == expected
for port in range(1, 65536):
    assert parse_port(str(port)) == port
print('Additional boundary, format, and full valid-range checks passed.')
PY"

